import{_ as s,a as t,b as a,c as n}from"./chunks/dataset_piscines.CSxrKepq.js";import{_ as i,o as l,c as o,a0 as r}from"./chunks/framework.Ckbw5VQO.js";const f=JSON.parse('{"title":"Jeu de données","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models/dataset.md","filePath":"fr/guide/models/dataset.md"}'),d={name:"fr/guide/models/dataset.md"};function p(u,e,c,g,h,m){return l(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="jeu-de-donnees" tabindex="-1">Jeu de données <a class="header-anchor" href="#jeu-de-donnees" aria-label="Permalink to &quot;Jeu de données&quot;">​</a></h1><p>Dans <strong>geo-ml</strong>, il n&#39;y a <strong>aucune annotation manuelle</strong>. C&#39;est le principe central du projet : les labels existent déjà, sous forme de données vectorielles ouvertes et gratuites couvrant toute la France. Les polygones de bâtiments proviennent de la <strong>BD TOPO IGN</strong>, ceux des piscines d&#39;<strong>OpenStreetMap</strong>.</p><p>Le rôle du pipeline est donc uniquement mécanique : télécharger des tuiles satellitaires IGN, assembler des mosaïques, convertir les polygones GPS en boîtes exprimées en pixels, puis découper le tout en fenêtres 640×640 au format attendu par YOLO.</p><div class="tip custom-block"><p class="custom-block-title">Aucune annotation manuelle</p><p>Les labels couvrent toute la France. On télécharge, on convertit, on entraîne, sans jamais dessiner une boîte à la main.</p></div><h2 id="sources-des-labels" tabindex="-1">Sources des labels <a class="header-anchor" href="#sources-des-labels" aria-label="Permalink to &quot;Sources des labels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Objet</th><th>Source</th><th>Couche / tag</th></tr></thead><tbody><tr><td><strong>Bâtiments</strong></td><td><a href="https://geoservices.ign.fr/bdtopo" target="_blank" rel="noreferrer">BD TOPO IGN</a></td><td><code>BDTOPO_V3:batiment</code></td></tr><tr><td><strong>Piscines</strong></td><td><a href="https://www.openstreetmap.org/" target="_blank" rel="noreferrer">OpenStreetMap</a></td><td><code>leisure=swimming_pool</code></td></tr></tbody></table><p>Les deux sources renvoient des <strong>polygones GPS</strong> (GeoJSON) que le pipeline convertit ensuite en bounding boxes pixel.</p><h2 id="format-yolo" tabindex="-1">Format YOLO <a class="header-anchor" href="#format-yolo" aria-label="Permalink to &quot;Format YOLO&quot;">​</a></h2><p>YOLOv8 attend un dataset structuré autour d&#39;un fichier de configuration <code>dataset.yaml</code> qui décrit les chemins et les noms de classes. Voir le <a href="https://docs.ultralytics.com/datasets/detect#supported-dataset-formats" target="_blank" rel="noreferrer">format officiel Ultralytics</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model/dataset/&lt;modèle&gt;/</span></span>
<span class="line"><span>├── dataset.yaml          ← chemins + noms de classes</span></span>
<span class="line"><span>├── images/</span></span>
<span class="line"><span>│   ├── train/  *.jpg     ← fenêtres 640×640 (80 %)</span></span>
<span class="line"><span>│   └── val/    *.jpg     ← fenêtres 640×640 (20 %)</span></span>
<span class="line"><span>└── labels/</span></span>
<span class="line"><span>    ├── train/  *.txt     ← une ligne par objet</span></span>
<span class="line"><span>    └── val/    *.txt</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title"><code>train/</code> vs <code>val/</code></p><p>Le dataset est découpé <strong>80 % / 20 %</strong> au moment de l&#39;écriture :</p><ul><li><strong><code>train/</code></strong>: les images que le modèle voit pendant l&#39;entraînement. Il calcule ses erreurs dessus et ajuste ses poids à chaque passe.</li><li><strong><code>val/</code></strong>: les images que le modèle ne voit <strong>jamais</strong> pendant l&#39;entraînement. Elles servent uniquement à mesurer sa qualité réelle à la fin de chaque epoch. Si la performance sur <code>val</code> se dégrade alors que celle sur <code>train</code> continue de s&#39;améliorer, c&#39;est le signe d&#39;un <strong>sur-apprentissage</strong> (<em>overfitting</em>).</li></ul></div><h3 id="structure-d-un-fichier-de-labels" tabindex="-1">Structure d&#39;un fichier de labels <a class="header-anchor" href="#structure-d-un-fichier-de-labels" aria-label="Permalink to &quot;Structure d&#39;un fichier de labels&quot;">​</a></h3><p>Chaque image <code>images/train/000042.jpg</code> possède un fichier <code>labels/train/000042.txt</code> associé. Chaque ligne du <code>.txt</code> décrit <strong>un objet</strong> :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0  0.666  0.655  0.156  0.181</span></span>
<span class="line"><span>↑    ↑      ↑      ↑      ↑</span></span>
<span class="line"><span>class  cx    cy     w      h    (tout normalisé entre 0.0 et 1.0)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Détail des champs</p><ul><li><strong><code>class</code></strong>: identifiant de la classe (<code>0</code> = bâtiment ou piscine selon le modèle). Un seul entier.</li><li><strong><code>cx</code>, <code>cy</code></strong>: coordonnées du <strong>centre</strong> de la boîte, normalisées entre <code>0.0</code> et <code>1.0</code> (<code>0</code> = bord gauche/haut, <code>1</code> = bord droit/bas).</li><li><strong><code>w</code>, <code>h</code></strong>: <strong>largeur</strong> et <strong>hauteur</strong> de la boîte, normalisées de la même façon. Tout est relatif à l&#39;image 640×640 : aucun pixel absolu.</li></ul></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dataset.yaml (généré automatiquement)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/abs/path/to/model/dataset/buildings</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">train</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">images/train</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">images/val</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">building</span></span></code></pre></div><h2 id="vue-d-ensemble-du-pipeline" tabindex="-1">Vue d&#39;ensemble du pipeline <a class="header-anchor" href="#vue-d-ensemble-du-pipeline" aria-label="Permalink to &quot;Vue d&#39;ensemble du pipeline&quot;">​</a></h2><p>Le pipeline part de deux sources de données distinctes, l&#39;une vectorielle (les annotations), l&#39;autre raster (l&#39;imagerie), qui finissent par se rejoindre pour produire le dataset final.</p><img src="`+s+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><p><strong>1. Récupération des annotations (source vectorielle)</strong></p><ul><li>Téléchargement des polygones GPS depuis les données ouvertes : <strong>BD TOPO</strong> (via WFS) et <strong>OpenStreetMap</strong> (via Overpass).</li><li>Ces polygones délimitent les objets à détecter (piscines, bâtiments).</li></ul><p><strong>2. Récupération de l&#39;imagerie (source raster)</strong></p><ul><li>Téléchargement des tuiles <strong>256×256 px</strong> depuis <strong>IGN WMTS</strong> (<code>data.geopf.fr</code>), au zoom 19 (~20 cm/px).</li><li>Mise en cache disque dans <code>model/dataset/_tilecache/</code> pour éviter de re-télécharger les mêmes tuiles.</li></ul><p><strong>3. Assemblage de la mosaïque</strong></p><ul><li>Assemblage de <strong>4×4 tuiles</strong> en une <strong>mosaïque 1024×1024 px</strong> (~200 m × 200 m au sol), à résolution native.</li></ul><p><strong>4. Conversion des coordonnées</strong></p><ul><li>Les polygones GPS sont projetés sur la mosaïque : conversion <strong>GPS → pixel</strong>, ce qui produit des <strong>bounding boxes</strong> exprimées en pixels.</li></ul><p><strong>5. Découpe en fenêtres</strong></p><ul><li>La mosaïque est découpée en <strong>fenêtres 640×640 px</strong> (la taille d&#39;entrée de YOLO), selon une stratégie de découpe propre à chaque modèle.</li></ul><p><strong>6. Génération du dataset final</strong></p><ul><li>Chaque fenêtre produit une paire image + annotations, répartie entre entraînement et validation : <ul><li><code>images/train/</code> et <code>images/val/</code> → les images <code>*.jpg</code></li><li><code>labels/train/</code> et <code>labels/val/</code> → les annotations <code>*.txt</code> (format YOLO)</li></ul></li></ul><h3 id="pourquoi-assembler-une-mosaique" tabindex="-1">Pourquoi assembler une mosaïque ? <a class="header-anchor" href="#pourquoi-assembler-une-mosaique" aria-label="Permalink to &quot;Pourquoi assembler une mosaïque ?&quot;">​</a></h3><p>Une tuile IGN brute fait 256×256 px, trop petite pour une fenêtre YOLO de 640×640. L&#39;upscaler floute l&#39;image et annule l&#39;intérêt de la haute résolution IGN. En assemblant 4×4 tuiles, on obtient une mosaïque 1024×1024 px à résolution native, dans laquelle on peut découper plusieurs fenêtres 640×640. C&#39;est aussi exactement la même échelle qu&#39;à l&#39;inférence, ce qui garantit que le modèle voit la même résolution à l&#39;entraînement et en production.</p><img src="'+t+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><h2 id="deux-strategies-selon-la-densite" tabindex="-1">Deux stratégies selon la densité <a class="header-anchor" href="#deux-strategies-selon-la-densite" aria-label="Permalink to &quot;Deux stratégies selon la densité&quot;">​</a></h2><p>Bâtiments et piscines ont une répartition très différente dans l&#39;espace. Le pipeline adapte donc sa stratégie de découpe à chaque type d&#39;objet.</p><h3 id="batiments-fenetre-glissante-sur-grille" tabindex="-1">Bâtiments - fenêtre glissante sur grille <a class="header-anchor" href="#batiments-fenetre-glissante-sur-grille" aria-label="Permalink to &quot;Bâtiments - fenêtre glissante sur grille&quot;">​</a></h3><p>Les bâtiments sont <strong>denses et uniformément répartis</strong>. Pour chaque zone, on assemble une grande mosaïque puis on fait <strong>glisser une fenêtre 640×640 avec 25 % de recouvrement</strong> sur toute la surface, afin de garantir une couverture exhaustive sans couper d&#39;objet en bordure.</p><img src="'+a+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><p><strong>Étapes pour chaque zone :</strong></p><ol><li>Télécharger les tuiles IGN → assembler la mosaïque.</li><li>Requêter <strong>BD TOPO WFS</strong> pour les polygones de bâtiments de la zone.</li><li>Convertir les polygones GPS → bboxes pixel sur la mosaïque.</li><li>Faire glisser la fenêtre 640×640 → écrire image + labels YOLO.</li></ol><h3 id="piscines-fenetre-centree-avec-jitter" tabindex="-1">Piscines - fenêtre centrée avec jitter <a class="header-anchor" href="#piscines-fenetre-centree-avec-jitter" aria-label="Permalink to &quot;Piscines - fenêtre centrée avec jitter&quot;">​</a></h3><p>Les piscines sont <strong>rares et dispersées</strong> : une grille produirait surtout des images vides. À la place, pour <strong>chaque piscine</strong>, on télécharge une mosaïque centrée dessus, puis on découpe une fenêtre avec un décalage aléatoire (<strong>jitter ±120 px</strong>) afin d&#39;améliorer l&#39;invariance à la position.</p><img src="'+n+`" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><p><strong>Étapes pour chaque zone :</strong></p><ol><li>Requêter <strong>OSM Overpass</strong> → polygones <code>leisure=swimming_pool</code>.</li><li>Filtrer les piscines hors-norme (<code>&lt; 1,5 m</code> ou <code>&gt; 35 m</code>).</li><li>Pour chaque piscine : télécharger une mosaïque centrée.</li><li>Découper une fenêtre 640×640 avec jitter → labelliser <strong>toutes</strong> les piscines visibles → écrire.</li></ol><div class="warning custom-block"><p class="custom-block-title">Labelliser toutes les piscines de la fenêtre</p><p>Si une fenêtre contient 3 piscines mais qu&#39;on n&#39;en marque qu&#39;une, on apprend au modèle que les 2 autres sont du fond → <strong>faux négatifs</strong>. Le script labellise donc <strong>toutes</strong> les piscines présentes dans la fenêtre, pas seulement celle qui a servi au centrage.</p></div><h2 id="telecharger-le-jeu-de-donnees" tabindex="-1">Télécharger le jeu de données <a class="header-anchor" href="#telecharger-le-jeu-de-donnees" aria-label="Permalink to &quot;Télécharger le jeu de données&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">conda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> geoml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.dataset.main</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # bâtiments + piscines (défaut)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.dataset.main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --buildings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # bâtiments seulement</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.dataset.main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pools</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # piscines seulement</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><em>(aucun)</em></td><td>Génère les deux datasets (bâtiments + piscines)</td></tr><tr><td><code>--buildings</code></td><td>Génère uniquement le dataset bâtiments (BD TOPO WFS)</td></tr><tr><td><code>--pools</code></td><td>Génère uniquement le dataset piscines (OSM Overpass)</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">imprécision du jeu de données</p><p>Les polygones BD TOPO et OSM ne sont pas toujours <strong>parfaitement alignés</strong> avec l&#39;orthophoto IGN, un décalage de 1 à 2 m est courant. Les boîtes sont donc parfois légèrement décalées. YOLO tolère bien ce bruit d&#39;étiquetage, mais c&#39;est la principale source d&#39;imprécision du jeu de données.</p></div>`,51)])])}const v=i(d,[["render",p]]);export{f as __pageData,v as default};
